import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"六州歌头·东风著意","description":"","frontmatter":{"title":"六州歌头·东风著意","date":"2026-11-12T00:00:00.000Z","seq":59,"categories":["美文","宋词三百首"],"collection":"《宋词三百首》","tags":["宋词三百首","宋"],"poem":true,"author":"韩元吉","source_book":"宋词三百首"},"headers":[],"relativePath":"blogs/宋词三百首/六州歌头·东风著意.md","filePath":"blogs/宋词三百首/六州歌头·东风著意.md"}'),o={name:"blogs/宋词三百首/六州歌头·东风著意.md"};function c(l,a,n,m,_,z){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="六州歌头·东风著意" tabindex="-1">六州歌头·东风著意 <a class="header-anchor" href="#六州歌头·东风著意" aria-label="Permalink to &quot;六州歌头·东风著意&quot;">​</a></h1><p class="poem-meta">宋 · 韩元吉</p><div class="poem"><p class="poem-stanza">东风著意。</p><p class="poem-stanza">先上小桃枝。</p><p class="poem-stanza">红粉腻。</p><p class="poem-stanza">娇如醉。</p><p class="poem-stanza">倚朱扉。</p><p class="poem-stanza">记年时。</p><p class="poem-stanza">隐映新妆，面临水岸。</p><p class="poem-stanza">春将半。</p><p class="poem-stanza">云日暖。</p><p class="poem-stanza">斜桥转。</p><p class="poem-stanza">夹城西。</p><p class="poem-stanza">草软莎平跋马，垂杨渡、玉勒争嘶。</p><p class="poem-stanza">认蛾眉凝笑，脸薄拂燕支。</p><p class="poem-stanza">绣户曾窥。</p><p class="poem-stanza">恨依依。</p><p class="poem-stanza">共携手处。</p><p class="poem-stanza">香如雾。</p><p class="poem-stanza">红随步。</p><p class="poem-stanza">怨春迟。</p><p class="poem-stanza">消瘦损。</p><p class="poem-stanza">凭谁问。</p><p class="poem-stanza">只花知。</p><p class="poem-stanza">泪空垂。</p><p class="poem-stanza">旧日堂前燕，和烟雨，又双飞。</p><p class="poem-stanza">人自老。</p><p class="poem-stanza">春长好。</p><p class="poem-stanza">梦佳期。</p><p class="poem-stanza">前度刘郎，几许风流地，花也应悲。</p><p class="poem-stanza">但茫茫暮霭，目断武陵溪。</p><p class="poem-stanza">往事难追。</p></div>',3)])])}const d=s(o,[["render",c]]);export{i as __pageData,d as default};
